func TestVisionReadsEnglishAsEnUs(emonT *testing.T) {
	var out *port.Cells = port.NewCells()
	port.AssertEq(emonT, ocrloc.OlLocales(3, 1701734144, out), 1, "eng is one tag")
	port.AssertEq(emonT, port.CellsLen(out), 5, "en-US")
	port.AssertEq(emonT, port.CellsAt(out, 0), 101, "e")
	port.AssertEq(emonT, port.CellsAt(out, 1), 110, "n")
	port.AssertEq(emonT, port.CellsAt(out, 2), 45, "-")
	port.AssertEq(emonT, port.CellsAt(out, 3), 85, "U")
	port.AssertEq(emonT, port.CellsAt(out, 4), 83, "S")
}

func TestVisionNamesTheTwoChineseModelsByScript(emonT *testing.T) {
	var out *port.Cells = port.NewCells()
	port.AssertEq(emonT, ocrloc.OlLocales(3, 1667789568, out), 1, "chs")
	port.AssertEq(emonT, port.CellsLen(out), 7, "zh-Hans")
	port.AssertEq(emonT, port.CellsAt(out, 3), 72, "Hans' H")
	port.AssertEq(emonT, ocrloc.OlLocales(3, 1667789824, out), 1, "cht")
	port.AssertEq(emonT, port.CellsLen(out), 7, "zh-Hant")
	port.AssertEq(emonT, port.CellsAt(out, 6), 116, "Hant ends in t")
}

func TestAScriptIsEveryLanguageVisionReadsInIt(emonT *testing.T) {
	var out *port.Cells = port.NewCells()
	port.AssertEq(emonT, ocrloc.OlLocales(3, ocrport.ScLatn(), out), 6, "Latin: en fr it de es pt")
	port.AssertEq(emonT, port.CellsLen(out), 35, "six five-letter tags and five commas")
	port.AssertEq(emonT, ocrloc.OlLocales(3, ocrport.ScHani(), out), 2, "Han: both Chinese scripts")
	port.AssertEq(emonT, port.CellsLen(out), 15, "zh-Hans,zh-Hant")
	port.AssertEq(emonT, ocrloc.OlLocales(3, ocrport.ScCyrl(), out), 2, "Cyrillic: Russian and Ukrainian")
	port.AssertEq(emonT, ocrloc.OlLocales(3, ocrport.ScJpan(), out), 1, "Japanese")
	port.AssertEq(emonT, ocrloc.OlLocales(3, ocrport.ScThai(), out), 1, "Thai")
}

func TestALanguageTheEngineHasNoTagForIsNoneAndTheListIsCleared(emonT *testing.T) {
	var out *port.Cells = port.NewCells()
	port.AssertEq(emonT, ocrloc.OlLocales(3, 1701734144, out), 1, "eng first")
	port.AssertEq(emonT, ocrloc.OlLocales(3, 2020501504, out), 0, "xyz has no tag")
	port.AssertEq(emonT, port.CellsLen(out), 0, "the list is cleared each time")
	port.AssertEq(emonT, ocrloc.OlLocales(1, 1701734144, out), 0, "Tesseract's languages are emon.ocrtess's")
	port.AssertEq(emonT, port.CellsLen(out), 0, "no tag for an engine with no table here")
}

func TestWindowsHasItsOwnLanguageTags(emonT *testing.T) {
	var out *port.Cells = port.NewCells()
	port.AssertEq(emonT, ocrloc.OlLocales(5, 1701734144, out), 1, "eng")
	port.AssertEq(emonT, port.CellsLen(out), 5, "en-US")
	port.AssertEq(emonT, ocrloc.OlLocales(5, 1667789568, out), 1, "chs")
	port.AssertEq(emonT, port.CellsLen(out), 10, "zh-Hans-CN")
	port.AssertEq(emonT, ocrloc.OlLocales(5, 1986618624, out), 1, "vie")
	port.AssertEq(emonT, port.CellsLen(out), 5, "vi-VN")
	port.AssertEq(emonT, port.CellsAt(out, 4), 78, "Windows spells Vietnam VN, Vision VT")
	port.AssertEq(emonT, ocrloc.OlLocales(3, 1986618624, out), 1, "vie under Vision")
	port.AssertEq(emonT, port.CellsAt(out, 4), 84, "vi-VT")
}

